#include "core/cheque_service.h"
#include "core/database.h"
#include <QStringList>
namespace pos { ChequeService::ChequeService(std::shared_ptr<Database> db):db_(std::move(db)){} QString ChequeService::record(const Cheque& c){if((c.direction!="received"&&c.direction!="issued")||c.number.trimmed().isEmpty()||c.amount<=0||!c.dueDate.isValid())throw DatabaseError("invalid cheque");Transaction tx(db_->handle());const auto id=uuid();auto q=db_->prepare("INSERT INTO cheques(id,direction,party_id,cheque_no,bank,amount_paisa,due_date,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)");q.bind(1,id);q.bind(2,c.direction);if(c.partyId.isEmpty())q.bindNull(3);else q.bind(3,c.partyId);q.bind(4,c.number.trimmed());q.bind(5,c.bank.trimmed());q.bind(6,c.amount);q.bind(7,c.dueDate.toString(Qt::ISODate));q.bind(8,"pending");q.bind(9,utcNow());q.execute();tx.commit();return id;} void ChequeService::setStatus(const QString& id,const QString& status){if(!QStringList{"pending","deposited","cleared","bounced"}.contains(status))throw DatabaseError("invalid cheque status");Transaction tx(db_->handle());auto q=db_->prepare("UPDATE cheques SET status=? WHERE id=? AND status!='cleared'");q.bind(1,status);q.bind(2,id);q.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("cheque not found or already cleared");tx.commit();} QList<Cheque> ChequeService::dueBy(const QDate& date)const{QList<Cheque> result;auto q=db_->prepare("SELECT id,direction,party_id,cheque_no,bank,amount_paisa,due_date,status FROM cheques WHERE status='pending' AND due_date<=? ORDER BY due_date");q.bind(1,date.toString(Qt::ISODate));while(q.stepRow())result.append({q.text(0),q.text(1),q.text(2),q.text(3),q.text(4),q.text(7),q.integer(5),QDate::fromString(q.text(6),Qt::ISODate)});return result;} }
